// Build RAG context string from historical trades
const items = $input.all();

if (items.length === 0) {
  return {
    json: {
      ragContext: 'No historical context available.',
      ragCount: 0
    }
  };
}

const contextLines = items.map((item, idx) => {
  const data = item.json;
  const outcome = data.is_win === true ? '✓ WIN' : 
                  data.is_win === false ? '✗ LOSS' : 
                  '⏳ PENDING';
  const similarity = data.similarity ? ` (similarity: ${parseFloat(data.similarity).toFixed(3)})` : '';

  return `${idx + 1}. [${data.created_at.split('T')[0]}] ${data.symbol} ${data.timeframe} - ${data.direction} ${outcome}${similarity}
   Confidence: ${(parseFloat(data.confidence) * 100).toFixed(1)}%
   Rationale: ${data.rationale}`;
});

const ragContext = contextLines.join('\n\n');

return {
  json: {
    ragContext: ragContext,
    ragCount: items.length,
    symbol: items[0].json.symbol
  }
};

// Build Grok API prompt with RAG context
const symbol = $json.symbol || 'EURUSD';
const timeframe = $json.timeframe || 'M30';
const marketSummary = $json.marketSummary || 'Current market conditions';
const ragContext = $json.ragContext || 'No historical context available.';

const prompt = `You are an expert forex trading analyst. Analyze the current market conditions and provide a trading recommendation.

**CURRENT MARKET:**
- Symbol: ${symbol}
- Timeframe: ${timeframe}
- Market Summary: ${marketSummary}

**HISTORICAL CONTEXT (Similar Past Trades):**
${ragContext}

**YOUR TASK:**
Based on the current market conditions and historical patterns, provide a trading recommendation.

**CRITICAL: You MUST respond with ONLY valid JSON. No markdown, no code blocks, no explanation - just pure JSON.**

**REQUIRED JSON SCHEMA:**
{
  "symbol": "${symbol}",
  "timeframe": "${timeframe}",
  "direction": "LONG" | "SHORT" | "FLAT",
  "entry_price": <number>,
  "stop_loss": <number>,
  "take_profit": <number>,
  "confidence": <0.0 to 1.0>,
  "rationale": "<brief explanation>",
  "notes": "<optional risk factors or additional comments>"
}

**RULES:**
1. direction must be exactly "LONG", "SHORT", or "FLAT"
2. confidence must be between 0.0 and 1.0 (e.g., 0.75 for 75% confidence)
3. All prices must be realistic for ${symbol}
4. If market is unclear or risky, use "FLAT" and lower confidence
5. Base your analysis on technical patterns, sentiment, and historical outcomes
6. Consider win/loss patterns from historical context

**RESPOND WITH JSON ONLY:**`;

return {
  json: {
    prompt: prompt,
    symbol: symbol,
    timeframe: timeframe,
    ragContext: ragContext,
    ragCount: $json.ragCount || 0
  }
};

